# ══════════════════════════════════════════════════════════════════
# §2.3 的排序表：**由闭式解生成，不手填**
# ⛔ 2026-09-17 红队抓到：这张表原来八行全是手打的，其中一行
#    「省显存 9.14 GiB × 每 GiB 付 7.70」算出来是 70 TFLOP，
#    「重算代价」那一栏却写着 39.08 —— 另外七行都对得上，就它不对。
# ⭐ 而这张表的卖点正是它下面那句「你拿 config 自己也能排一遍」。
#    照着排的人**会正好撞上那一行**，然后开始怀疑整条闭式解。
# 判据：**一张宣称「按某条公式排出来」的表，就得真的用那条公式生成。**
#    手填的表里，「大部分行能对上」不构成任何保证 —— 错的那行长得跟对的一样。
# ══════════════════════════════════════════════════════════════════
GIB_F = 2 ** 30 / 1e12        # FLOPs/字节 → TFLOP/GiB
DTYPE_B = 2                   # bf16
S_BASE = 4096                 # ⭐ 本讲基准：V3 预训练真实序列长度（14.8T token 全在这档）
S_LONG = 131072               # 长上下文扩训（预训练之后各一千步）
S_RATIO = S_LONG // S_BASE    # ＝ 32，激活线性缩放的倍数
D_V3 = 7168                   # V3 的模型宽度（＝ 残差流的宽度，gate/up 的输入）
# ⛔ D_V3 原来的注释写的是「最宽的那个线性层的输入」——&#160;**在 MLA 上不成立**。
#    o_proj 吃的是 128 头 × 128 ＝ 16,384，比 d_model 宽一倍。
#    这正是「老约束在新架构上已被解除」的标准案例：MHA 里 heads × head_dim ＝ hidden，
#    MLA 里不是。交点、倍数、名次全都建在这个常数上，所以它单列并跟 §1.7 的表对账。
W_WIDEST_V3 = 128 * 128       # o_proj 的输入宽 ——&#160;全层最宽的线性层
N_ACT_L = 585.3e6             # 一层的激活参数量（MLA ＋ 被选中的 9 个专家）
H_V3, DQK_V3, DV_V3 = 128, 192, 128

def _step_tf(S):
    """一层跑完一个 step（前向 ＋ 反向 ≈ 3 遍）要多少 TFLOP。
    ⛔ 2,571 这个数原来是**空降的** —— 而「只多付 1.9%」整个结论拿它当分母。
       三位评审都点名了。现在它由 S 算出来，换基准自动跟着走。
    ⭐ 两项的 S 次数不同（线性 ∝ S，attention ∝ S²），**这正是翻转的来源**。"""
    lin = 2 * N_ACT_L * S
    att = S * S * H_V3 * (DQK_V3 + DV_V3)
    return 3 * (lin + att) / 1e12

def _att_share(S):
    lin, att = 2 * N_ACT_L * S, S * S * H_V3 * (DQK_V3 + DV_V3)
    return att / (lin + att)

# (名称, 省显存 GiB, 每字节 FLOPs, 结论)
#   线性层：每字节 FLOPs ＝ **输入宽度**（2·S·k·n ÷ (S·n·2)，S 和 n 全约掉）
#   逐元素：每元素约四五次运算，bf16 折下来 ≈ **2 次/字节**。
#     ⚠️ 这是个估算，所以两行**取同一个数** —— 它们之间分不出先后，
#     而且取 2 还是取 3，显示出来都是「~0」，排序也不变。
#     ⛔ 不要为了让表看起来精确而给它们编两个不同的值。
#   attention：随序列长度线性上升，V3 那套头维度下约 1.25·S
# (名字, 128K 上省多少 GiB, 每字节代价 FLOPs/B)
# ⛔ GiB 一列原来是**手填的 128K 常量**，而这一段正文的卖点是「你拿 config 自己也能排一遍」。
#    现在按基准缩放；每字节代价里只有 attention 带 S，其余是输入宽度、与 S 无关。
# ⭐⭐ 而这正是翻转的全部机制：**七行不动，一行在动。**
# ⛔⛔ 2026-09-19 T09：这张表原来**加起来对不上一层**。
#   八行合计 66.64 GiB，而一层 MoE 块是 71.14 ——&#160;缺 4.50。
#   评审报的是「9.14 那一行应该是 10.08」，但改完仍差 3.56 ——&#160;**缺的不止一行**。
#   ⭐ 根因：这张表原来是**手写的**，没有跟 §1.7 那张宽度表对过账。
#     漏掉的是 MLA 的两个 norm 输出和 Q 降维那一份 layernorm 输出（都是逐元素、pb≈2）。
#   ⭐⭐ 重导之后总和自动闭合：候选池 284,224 ＋ 入口 7,168 ＝ 291,392 ＝ 一层。
#     而候选池在 128K 上正好 69.39 GiB ——&#160;**跟正文早就写着的「可重算池 69.4」对上了**，
#     说明分母一直是对的，只是表少列了几行。
#   ⛔ 判据：**一张「把某个整体拆开」的表，必须断言它加回去等于那个整体。**
#
# (名字, 等效宽度, 每字节代价 ＝ 产生它的那个算子的输入宽度)
PER_BYTE_W = [
    ("logsumexp（attention 副产物，fp32）",        256, 0.0),
    ("RMSNorm 输出（3 份，逐元素）",              15872, 2.0),
    ("SwiGLU 乘积 9 份（逐元素）",                18432, 2.0),
    ("K/V 解压（输入宽 512）",                    32768, 512.0),
    ("Q 展开（输入宽 1,536）",                    24576, 1536.0),
    ("专家输出 9 份（输入宽 2,048）",              64512, 2048.0),
    ("gate / up / 路由 / 降维（输入宽 7,168）",    39744, float(D_V3)),
    # ⛔ 这一份原来跟另外三个 RMSNorm 输出捆在一起按「逐元素、白捡」计价（2026-09-19 红队查出）。
    #    它是 MLA 之后的残差流 ＝ o_proj 的输出 ——&#160;要重算它就得跑 o_proj，
    #    而 o_proj 的输入是 128 头 × 128 ＝ 16,384，**是这一层最宽的线性层输入**。
    #    ⭐ 反例一直印在 §1.7 那张表上（「attention 输出　128 头 × 128 ＝ 16,384」），
    #      隔了 100 行没对上账 ——&#160;所以下面那条 assert 直接跟 §1.7 的表绑死。
    ("MLA 后的残差流（＝ o_proj 输出，输入宽 16,384）", 7168, float(W_WIDEST_V3)),
    ("attention 输出",                           16384, None),   # None ＝ 1.25·S
]
ENTRY_W = 7168          # 入口那一份 ——&#160;重算模式下留的就是它，不在候选池里
_pool_w = sum(w for _, w, _ in PER_BYTE_W)
# ⛔ 2026-09-22：291,392 → 226,880。差的 64,512 正是那条被删掉的「派发九份」——
#   它是实现产物不是必需量（见 _MOE_ROWS 里那段）。⭐ 这个锚点**必须跟着改**，
#   不改就是拿旧的错数去校验新的对数；改了要说清为什么，否则跟「把测试改绿」没区别。
assert _pool_w + ENTRY_W == 226880, \
    "候选池 %d ＋ 入口 %d 加不回一层 MoE 块的 226,880" % (_pool_w, ENTRY_W)
CUT = 3.0        # 「比值小于 3 全收下」——&#160;正文里说清了这是我定的，不是算出来的


def _per_byte(S):
    """按序列长度 S 排一遍。⭐ 返回已按「每 GiB 付」升序排好的行。"""
    return sorted([(nm, w * DTYPE_B * S / 2 ** 30, 1.25 * S if pb is None else pb)
                   for nm, w, pb in PER_BYTE_W], key=lambda r: r[2])


def _verdict(ratio):
    """⛔ 原来「白捡/划算/边际/绝不」是**手写在每一行上**的，
       换个基准就会留下一行说谎的标签。现在从比值算出来。"""
    if ratio < 0.05:  return "白捡"
    if ratio < CUT:   return "划算"
    if ratio < 20.0:  return "边际"
    return "绝不"


_POOL_B = _pool_w * DTYPE_B * S_BASE

# ⭐ §1.6 主线要回答「一层里最大的是哪一项」——&#160;由这张表直接算，不手填。
#   （2026-09-20 第 8 轮开讲时补：原来主线把这一问整个推给了折叠块，
#    可下一节整节都在挑「该扔哪个」，不先说哪几项占地方就没法挑。）
#   ⛔ 我一开始以为大头是 attention，一算是 MoE 的九份复制 ——&#160;查了才没写错。
_L1 = {nm: w * DTYPE_B * S_BASE for nm, w, _ in PER_BYTE_W}
_L1["入口"] = ENTRY_W * DTYPE_B * S_BASE
_L1_TOT = sum(_L1.values())
_pc = lambda k: "%.0f%%" % (100.0 * _L1[k] / _L1_TOT)
_MOE_O_PCT = _pc("专家输出 9 份（输入宽 2,048）")
_MOE_S_PCT = _pc("SwiGLU 乘积 9 份（逐元素）")
_ATT_PCT   = _pc("attention 输出")
# ⛔ 2026-09-22：原来这里是三项（派发 ＋ 专家输出 ＋ SwiGLU）加起来「占一半」。
#   派发那一项作废之后剩两项，占比从约 50% 掉到约 37% ——
#   ⭐ 结论本身不变（**九份复制仍然是一层里最大的一块**），变的是它有多大。
_MOE_ALL   = sum(_L1[k] for k in ("专家输出 9 份（输入宽 2,048）",
                                  "SwiGLU 乘积 9 份（逐元素）"))
_MOE_ALL_PCT = "%.0f%%" % (100.0 * _MOE_ALL / _L1_TOT)
assert 33 < 100.0 * _MOE_ALL / _L1_TOT < 40, "九份复制的占比变了：%s" % _MOE_ALL_PCT
assert _L1["attention 输出"] < _L1["专家输出 9 份（输入宽 2,048）"], \
    "一层里最大的那一项不再是「专家输出九份」了？"

_ROWS_BASE = _per_byte(S_BASE)
_ROWS_LONG = _per_byte(S_LONG)

# 这一讲最值钱的那个论断，写成断言：**同一条判据，两个基准给出不同的名次。**
_att_base = [r for r in _ROWS_BASE if r[0] == "attention 输出"][0]
_att_long = [r for r in _ROWS_LONG if r[0] == "attention 输出"][0]
assert _ROWS_LONG[-1][0] == "attention 输出", "128K 上 attention 应该排最后（最贵）"
assert _ROWS_BASE[-1][0] != "attention 输出", \
    "4K 上 attention 不该再是最贵的那一个 —— 翻转没发生，去查斜率"
assert abs(_att_base[2] * GIB_F - 5.50) < 0.01 and abs(_att_long[2] * GIB_F - 175.92) < 0.01
# ⛔ 但**别把话说过头**：5.50 仍然高于 CUT ＝ 3，所以按本讲自己那条线，
#    4K 上 attention 依然不进「收下」那一批。它从「绝不」变成「边际」，不是变成「该重算」。
assert _att_base[2] * GIB_F > CUT, "4K 上 attention 仍在切线之上 —— 这条前提变了就要改正文"
assert _verdict(_att_base[2] * GIB_F) == "边际" and _verdict(_att_long[2] * GIB_F) == "绝不"

_rows, _prev = [], -1.0
for _name, _gib, _pb in _ROWS_BASE:
    _cost, _ratio = _gib * _pb * GIB_F, _pb * GIB_F
    assert _ratio >= _prev, "排序坏了：%s" % _name
    _prev = _ratio
    _v = _verdict(_ratio)
    _c = "~0" if _cost < 0.005 else "%.2f TFLOP" % _cost
    _r = "0" if _pb == 0 else ("~0" if _ratio < 0.05 else "%.2f" % _ratio)
    _b = (lambda x: "<b>%s</b>" % x) if _v in ("绝不", "边际") else (lambda x: x)
    _rows.append("<tr><td>%s</td><td>%s</td><td>%s</td><td><b>%s</b></td><td>%s</td></tr>"
                 % (_b(_name), _b("%.3f GiB" % _gib), _b(_c), _r, _b(_v)))

_TBL = ('<table>\n<thead><tr><th>张量</th><th>省显存</th><th>重算代价</th>'
        '<th>每 GiB 付</th><th>结论</th></tr></thead>\n<tbody>\n'
        + "\n".join(_rows) + "\n</tbody></table>")

# ⭐ 正文里引用这张表的三个数，也回头对一遍 —— 表改了正文没跟着改，
#    是这类「生成表 + 手写正文」最典型的下一个坑。
_cheap = [r for r in _ROWS_BASE if r[2] * GIB_F < CUT]
_CHEAP_GIB = sum(r[1] for r in _cheap)
_CHEAP_TF = sum(r[1] * r[2] * GIB_F for r in _cheap)
_CROSS = W_WIDEST_V3 / 1.25       # attention 追平**最宽线性层**的序列长度
# ⭐ 正文里凡是「交点是多少、表有几行、attention 排第几」，一律从这里取 ——
#   这一节反复出问题的模式就是「表是生成的、正文是手写的」，所以不再留手写的数。
_NROWS      = len(PER_BYTE_W)
_WIDEST_PB  = W_WIDEST_V3 * GIB_F
_RANK_BASE  = [r[0] for r in _ROWS_BASE].index("attention 输出") + 1
_RANK_LONG  = [r[0] for r in _ROWS_LONG].index("attention 输出") + 1
assert _RANK_LONG == _NROWS, "128K 上 attention 该排最后一名"
assert _RANK_BASE < _NROWS, "4K 上 attention 不该排最后 —— 翻转没发生"

# ⭐ 选择性 vs 全量：两个百分比与它们的性价比之比，全部由基准算出来。
_STEP_TF   = _step_tf(S_BASE)
_SEL_PCT   = 100.0 * _CHEAP_TF / _STEP_TF          # 选择性重算多付百分之几
# ⛔ _FULL_SAVE 原来写死 97.0，而同一个脚本自己算出来的是 95.81 —— 这是全篇唯一一个
#    「C 类手填常量」真的填错的地方（2026-09-19 审计查出）。它还撑着对外的「性价比 __EDGE__ 倍」。
#    改成从峰值占比推，跟 fig-recompute 用同一个口径。
_FULL_PCT  = 100.0 / 3.0          # 全量重算多付：在 fwd+bwd=3 上再加一次 fwd
# _FULL_SAVE / _EDGE 依赖 _PEAK_PCT，在下面峰值那一块算完之后才定义。
_SEL_SAVE = 100.0 * _CHEAP_GIB / (_POOL_B / 2 ** 30)   # 选择性换掉了池子的百分之几
# _EDGE 见下方峰值块之后（它依赖 _FULL_SAVE）。
# attention 跟它前一档的倍数 —— 128K 上最贵，4K 上它已经不在最后。
# ⛔ 这两个数原来是 22.857 / 0.714，因为分母用了 7,168。分母换成真正最宽的 16,384 之后
#    是 10.0 / 0.3125 ——&#160;代码本来就是算出来的，错的只有常数和正文。
_TIMES_LONG = _ROWS_LONG[-1][2] / _ROWS_LONG[-2][2]
_ATT_VS_WIDEST = _att_base[2] / float(W_WIDEST_V3)   # 4K 上 attention ÷ 最宽线性层
assert _ROWS_LONG[-2][2] == float(W_WIDEST_V3), \
    "128K 上第二贵的那行应该就是最宽线性层，现在是 %.0f" % _ROWS_LONG[-2][2]

for _nm, _got, _want in (("128K attention ÷ 最宽线性层", _TIMES_LONG, 10.0),
                         ("4K attention ÷ 最宽线性层", _ATT_VS_WIDEST, 0.3125),
                         ("4K 选择性占比", _SEL_PCT, 9.30),
                         ("一层一步 TFLOP", _STEP_TF, 16.45),
                         ("4K attention 占前向", 100 * _att_share(S_BASE), 12.53),
                         ("128K attention 占前向", 100 * _att_share(S_LONG), 82.11)):
    assert abs(_got - _want) < 0.02, "%s 算出 %.3f，期望 %.3f" % (_nm, _got, _want)

# ══════════════════════════════════════════════════════════════════
# §1.7 的两张激活表 —— 由「张量宽度」生成，序列长度只是一个变量。
#
# ⛔ 原来两张表是**手写的 GiB 数**，钉死在 S ＝ 131,072 上。现场定的基准是
#    **4K**（V3 预训练真实配置），一改就要手工改十几个数、还要改小计和总计 ——
#    那正是「改一处忘三处」的产地。
# ⭐ 判据：**一个数如果是算出来的，就让它在构建时算，不要让它在正文里躺着。**
#    改成这样之后，切基准只动 S_BASE 一个数，而 128K 的旧值成了回归锚点。

# (说明, 宽度怎么来的, 等效宽度, 每元素字节)
_MLA_ROWS = [
    ("norm 的输入（＝ 残差入口，<b>重算模式下唯一留的那份</b>）", "7,168", 7168, 2),
    ("norm 的输出", "7,168", 7168, 2),
    ("Q 降维结果（layernorm 前后各一份）", "2 × 1,536", 3072, 2),
    ("KV 降维结果（含 RoPE 那 64 维）", "576 ＋ 512", 1088, 2),
    ("<b>Q 展开后</b>", "128 头 × 192 ＝ <b>24,576</b>", 24576, 2),
    ("<b>K、V 解压后</b>", "128 头 × 256 ＝ <b>32,768</b>", 32768, 2),
    ("attention 输出", "128 头 × 128 ＝ 16,384", 16384, 2),
    ("logsumexp（fp32）", "128", 128, 4),
]
_MOE_ROWS = [
    ("norm 的输入 / 输出", "2 × 7,168", 14336, 2),
    ("路由分数", "256", 256, 2),
    # ⛔⛔ 2026-09-22 现场纠错，原话：「它输入给这九个专家的都是同一份。」
    #    ——&#160;对。这一行原来记 9 × 7,168 ＝ 504 MiB，是**把某个实现的做法
    #    当成了数学上的必需**。九个专家读的是同一块内存，而那块内存
    #    **上一行已经记过了**（norm 的输出）。所以必需的增量是 0。
    # ⭐ 九份是怎么冒出来的：MoE 跑起来通常先做一次 permute，按专家把 token
    #    重排成连续块，好让每个专家做一次高效的分组矩阵乘。那个重排缓冲区
    #    确实是副本，top-9 就是每个 token 出现九次。
    #    ⛔ 但有实现在反向里**重做一遍 permute** 而不存它 ——&#160;
    #    所以它是**实现选择**，写进必需账里就是虚报。
    # ⭐ 判据：**账上只记数学上非有不可的，实现才有的东西写进旁注。**
    ("派发给专家的那份", "＝ 上一行本身，<b>九个专家共用</b>", 0, 2),
    ("gate / up / SwiGLU 乘积", "3 × <b>9 份</b> × 2,048", 55296, 2),
    ("<b>专家输出（合并前）</b>", "<b>9 份</b> × 7,168", 64512, 2),
]
_DENSE_FFN_W = 3 * 18432 + 14336      # dense 层的 FFN 部分（MLA 那半边共用）
N_MOE_L, N_DENSE_L = 58, 3

def _bytes(rows, S):
    return sum(w * b for _, _, w, b in rows) * S

def _sz(nbytes):
    """⭐ 4K 上很多项不到 1 GiB —— 硬写 GiB 会变成一串 0.02，读者读不出量级。"""
    g = nbytes / 2 ** 30
    if g >= 1:
        return "%.2f GiB" % g
    m = nbytes / 2 ** 20
    # ⛔ 整数 MiB 会把 8.5 显示成 8（差 6%）—— 小数点后那一位在小项上是承重的
    return ("%.1f MiB" % m).replace(".0 MiB", " MiB") if m < 100 else "%.0f MiB" % m

def _act_tbl(rows, S, head2, total_label):
    body = "".join('<tr><td>%s</td><td>%s</td><td>%s</td></tr>' % (n, w, _sz(ww * bb * S))
                   for n, w, ww, bb in rows)
    return ('<table><thead><tr><th>留下的张量</th><th>%s</th><th>大小</th></tr></thead>'
            '<tbody>%s<tr><td><b>%s</b></td><td></td><td><b>约 %s</b></td></tr>'
            '</tbody></table>' % (head2, body, total_label, _sz(_bytes(rows, S))))

_MLA_B   = _bytes(_MLA_ROWS, S_BASE)
_MOE_B   = _bytes(_MOE_ROWS, S_BASE)
_LAYER_B = _MLA_B + _MOE_B
_DENSE_B = _MLA_B + _DENSE_FFN_W * DTYPE_B * S_BASE
_TOTAL_B = N_MOE_L * _LAYER_B + N_DENSE_L * _DENSE_B

# ⛔ 回归锚点：同一套宽度在 128K 上必须复现这几个数。
#   ⭐ 这才是「换基准」和「算错了」的分水岭 —— 没有它，改完只能靠感觉。
#
# ⛔⛔ 2026-09-22 这四个数**整体下修**，因为「派发九份」那一行作废了
#   （见 _MOE_ROWS 里那段：九个专家读的是同一块内存）。
#   旧值 → 新值：MLA 22.58（不动）· MoE 48.56 → 32.81 ·
#              一层 71.14 → 55.39 · 全模型 4.145 → 3.253 TiB
#   ⚠️ **改回归锚点是一件需要说明理由的事** —— 不说理由的话，它跟
#     「测试不过就把期望值改成实际值」在 diff 里长得一模一样。
#     这里的理由是：旧值复现的是一个**记错了的账**，不是一个被改坏的表。
for _nm, _got, _want in (
        ("MLA 小计",   _bytes(_MLA_ROWS, S_LONG) / 2 ** 30,                       22.58),
        ("MoE 小计",   _bytes(_MOE_ROWS, S_LONG) / 2 ** 30,                       32.81),
        ("一层 MoE 块", (_bytes(_MLA_ROWS, S_LONG) + _bytes(_MOE_ROWS, S_LONG)) / 2 ** 30, 55.39),
        ("全模型",     (N_MOE_L * (_bytes(_MLA_ROWS, S_LONG) + _bytes(_MOE_ROWS, S_LONG))
                        + N_DENSE_L * (_bytes(_MLA_ROWS, S_LONG)
                                       + _DENSE_FFN_W * DTYPE_B * S_LONG)) / 2 ** 40, 3.253)):
    assert abs(_got - _want) < 0.01, \
        "128K 锚点对不上：%s 算出 %.3f，期望 %.3f —— 宽度表被改坏了" % (_nm, _got, _want)

# 注意力分数矩阵是 S² 项，**不跟着 token 总数走** —— 它是唯一一个换基准时
# 要按平方缩的量。⭐ 这正是 §1.7 边界②该讲清楚的地方。
# ⛔⛔ 全量重算的峰值 ＝ 存档点 ＋ **当前正在重算的那一层的完整激活**。
#   原来只算了存档点（61 × 入口那一份 ＝ 106.75 GiB@128K），漏掉后面那一项 ——
#   而 §5.4 的 125M 例子和 §2.2 图 Ⓒ 用的都是**正确**口径，只有 671B 这个头号数字没做。
#   ⭐ 三位评审各自算出同一批数。这是全篇唯一一个**照抄会把集群配小 67%** 的数。
_CKPT_B     = (N_MOE_L + N_DENSE_L) * 7168 * DTYPE_B * S_BASE   # 每层只留入口那一份
_INFLIGHT_B = _LAYER_B                       # 在算的那一层，取 MoE 块（最坏情况）
_PEAK_B     = _CKPT_B + _INFLIGHT_B
_RECOMP_X   = _TOTAL_B / _PEAK_B             # 全量重算省多少倍
_PEAK_PCT   = 100.0 * _PEAK_B / _TOTAL_B
_FULL_SAVE = 100.0 - _PEAK_PCT    # 全量重算省掉的比例 —— 跟 fig-recompute 同一口径
# ⛔ 2026-09-22：95.81 → 95.13（省 23.9 倍 → 20.5 倍）。同一个原因：
#   分子分母都因为「派发九份」作废而变小，而分母（重算后峰值）里
#   存档点那一项没变，所以比例略降。⭐ 结论不动，量级不动。
assert abs(_FULL_SAVE - 95.13) < 0.05, "全量重算省的比例变了：%.2f" % _FULL_SAVE
_EDGE = (_SEL_SAVE / _SEL_PCT) / (_FULL_SAVE / _FULL_PCT)   # 选择性 vs 全量 的性价比之比
RESIDENT_B  = 671e9 * 16                     # 常驻块（每参数 16 字节）
_WS_SEQ     = RESIDENT_B / _PEAK_B           # 激活追平常驻需要多少条序列
_WS_TOK     = _WS_SEQ * S_BASE

# §1.6 的对照。⛔ 这里原来写的是「133 GiB 比整个模型的权重还大一截」——
#   方向反了：权重 bf16 是 1,250 GiB，133 GiB 只有它的九分之一（2026-09-19 红队查出）。
#   真正成立、而且更有力的说法是「两者涨得不一样」：权重固定，激活按 batch 线性叠。
#   所以这里算的是交叉点，不再拿两个孤立的数硬比大小。
_W_BF16_B  = 671e9 * DTYPE_B                 # 只有权重，不含梯度和优化器状态
_ACT_XOVER = _W_BF16_B / _TOTAL_B            # 激活追平**权重**要多少条 4K 序列
assert _W_BF16_B > _TOTAL_B, "激活反而比权重大了？先查 _TOTAL_B 的口径"
# ⛔ 2026-09-22：9.x → 12.0。激活总量小了，追平权重自然要更多条序列。
#   ⭐ 论点不变（**十几条就追平，而训练的 batch 从来不止十几条**），数动了。
assert 11.5 < _ACT_XOVER < 12.5, "激活追平权重的 batch 变了：%.2f" % _ACT_XOVER

# ⛔⛔ 2026-09-22 整组下修 —— 同一个根因（派发九份作废）。旧 → 新：
#   在算层 71.14 → 55.39 · 峰值 177.89 → 162.14 · 倍数 23.86 → 20.53
#   ⭐ 存档点那一项**一点没变**（106.75）——&#160;它只跟「每层留入口一份」有关，
#     跟专家里发生了什么无关。这一条正好说明这次改动的作用面在哪。
for _nm, _got, _want in (("存档点@128K",  _CKPT_B * S_RATIO / 2 ** 30,     106.75),
                         ("在算层@128K",  _INFLIGHT_B * S_RATIO / 2 ** 30,  55.39),
                         ("峰值@128K",    _PEAK_B * S_RATIO / 2 ** 30,     162.14),
                         ("省多少倍",     _RECOMP_X,                        20.53),
                         ("峰值占比",     _PEAK_PCT,                         4.87),
                         ("分水岭条数",   _WS_SEQ,                        1973.0),
                         ("分水岭 token", _WS_TOK / 1e6,                     8.08)):
    assert abs(_got - _want) < max(0.02, abs(_want) * 0.001), \
        "%s 算出 %.3f，期望 %.3f" % (_nm, _got, _want)

# ⭐⭐ §5.4 那句「比例跟 671B 上那笔几乎一样」是错的（6.7 倍 vs 23.9 倍）。
#   ⛔ 但光改掉它是浪费 ——&#160;这两个数为什么不一样，本身是条能带走的规律：
#        省多少倍 ＝ r ÷ (1 + r/L)     r ＝ 一层激活 ÷ 入口那一份，L ＝ 层数
#   分子是「一层里挂了多少东西」，分母那一项是「在算的那一层摊到每层头上」。
#   ⭐ 小模型**两项都吃亏**：r 小 2.7 倍，L 小 5 倍。所以它省得少是必然的，不是算错。
SMALL_L, SMALL_D = 12, 768
SMALL_LAYER_W = 2 * 768 + 3 * 768 + 768 + 3072 + 3072 + 768      # ＝ 11,520
_R_SMALL = SMALL_LAYER_W / float(SMALL_D)                         # ＝ 15.0
_R_V3    = (_LAYER_B / (DTYPE_B * S_BASE)) / 7168.0               # ＝ 40.7
_x_small = _R_SMALL / (1 + _R_SMALL / SMALL_L)
# ⭐⭐ 2026-09-20 第 19 轮：把「补上入口之后」那一对数也算出来。
#   ⛔ 它原来是手打的「r 约 16、省的倍数约 7.1」——&nbsp;而 r=16 代进同一个
#     式子只有 6.86。**整格就它一个数没过脚本，就它错了。**
#   ⭐ 判据：**一格里只要有一个数是手打的，它就是那一格里最可能错的那个**
#     ——&nbsp;因为别的数每次 build 都被重算一遍，只有它不会。
_R_SMALL_E = _R_SMALL + 1.0                       # 补一个残差入口（＝重算时留下的那份）
_x_small_e = _R_SMALL_E / (1 + _R_SMALL_E / SMALL_L)
assert abs(_x_small_e - 6.857) < 0.01, _x_small_e
_x_v3    = _R_V3 / (1 + _R_V3 / (N_MOE_L + N_DENSE_L))
# ⛔ 2026-09-22：V3 的 r 从 40.66 → 31.65（派发九份作废，一层里少挂了 9 份宽张量），
#   闭式估随之 24.395 → 20.84。⭐ 那条规律本身（小模型两项都吃亏）一个字没变。
for _nm, _got, _want in (("小模型 r", _R_SMALL, 15.0), ("V3 r", _R_V3, 31.65),
                         ("小模型省几倍", _x_small, 6.67), ("V3 闭式估", _x_v3, 20.839)):
    assert abs(_got - _want) < 0.02, "%s 算出 %.3f，期望 %.3f" % (_nm, _got, _want)
# ⚠️ 闭式给 V3 是 24.4，实测 23.9 ——&#160;差在那 3 层 dense 比 MoE 薄。
#   写进正文时说「约」，不要拿闭式冒充精确值。
assert abs(_x_v3 - _RECOMP_X) < 0.6

# §1.0 的「loss 刻度尺」——&#160;现场点名要讲清「loss 到底是怎么算的」。
#   ⛔ 全讲原来一次都没出现过「困惑度」「负对数」「对数似然」，
#      而 §6 整节在讲「loss 飞了」——&#160;读者手上**没有尺**，不知道飞到多少算飞。
#   ⭐ 刻度尺只用一个恒等式：困惑度 ＝ e^loss，不需要引任何人的实测值。
V_VOCAB = 129280                      # V3 词表（专题一核过：词表矩阵 129,280 × 7,168）
_L_RANDOM = math.log(V_VOCAB)         # 均匀瞎猜时的 loss ＝ ln V ＝ 11.77
assert abs(_L_RANDOM - 11.7697) < 1e-3

_SCALE = [
    (_L_RANDOM, "刚初始化，还没学任何东西",
     "在整个词表里均匀瞎猜 ——&nbsp;<b>这就是 loss 的上限</b>"),
    (6.0,  "学会了最基本的字频",  "相当于在几百个词里犹豫"),
    (4.0,  "语法大致对了",        "几十个词"),
    (3.0,  "像模像样的文本",      "二十个词上下"),
    (2.0,  "现代大模型预训练末期<b>大致落在这一档</b>", "七八个词"),
    (1.0,  "几乎能背出来了",      "两三个词 ——&nbsp;<b>正常预训练到不了这里</b>"),
]
#: nat → bit。⛔ 2026-09-21 补：这一列原来没有，而它恰恰是把「loss 是个抽象数」
#:   变成「模型每个 token 要花几个 bit」的那一步。现场卡在「nat 是什么」上，
#:   根子就是全讲没有一处把 nat 和 bit 摆在一起。
_NAT2BIT = math.log2(math.e)
assert abs(_NAT2BIT - 1.4426950) < 1e-6
assert abs(_L_RANDOM * _NAT2BIT - math.log2(V_VOCAB)) < 1e-6, \
    "瞎猜那一档换成 bit 必须正好等于 log2(词表)，对不上就是换算写错了"

_TBL_SCALE = ('<table><thead><tr><th>loss<br><span class="sub">nat/token</span></th>'
              '<th>换成 bit<br><span class="sub">＝ nat × 1.4427</span></th>'
              '<th>困惑度 ＝ e<sup>loss</sup></th>'
              '<th>大概是什么水平</th><th>「在几个词之间犹豫」</th></tr></thead><tbody>'
              + "".join(
                  # ⭐ 只有最上面那一行是**算出来的**（ln 129,280）；其余四档是按
                  #   公开模型的量级填的。原来它们长得一模一样，而这一讲自己的
                  #   招牌就是「算出来的和估出来的要分得清」——&#160;所以标出来。
                  ('<tr><td><b>%s</b>%s</td><td>%s</td><td>%s</td><td>%s</td>'
                   '<td><em>%s</em></td></tr>')
                  % ("%.2f" % v if abs(v - _L_RANDOM) < 1e-6 else "%.1f" % v,
                     ' <span class="sub">算出来的</span>'
                     if abs(v - _L_RANDOM) < 1e-6
                     else ' <span class="sub">量级</span>',
                     "<b>%.2f</b>" % (v * _NAT2BIT),
                     format(int(round(math.exp(v))), ","), what, feel)
                  for v, what, feel in _SCALE)
              + '</tbody></table>')

# ⛔⛔ §1.7 那两张表是**逐层**的，所以它们漏了一样不属于任何一层的东西：
#   最后那个投影吐出的 **logits**，形状 [S, 词表]。三位评审里有一位专门点了它。
#   ⭐ 它在 4K 上比表里最大的单个张量（K/V 解压 256 MiB）还大四倍。
_LOGITS_B      = S_BASE * V_VOCAB * DTYPE_B
_LOGITS_B_LONG = S_LONG * V_VOCAB * DTYPE_B
assert abs(_LOGITS_B / 2 ** 30 - 0.986) < 0.002

_ATTN_SCORE_B = 128 * S_BASE ** 2 * DTYPE_B
_ATTN_SCORE_LONG = 128 * S_LONG ** 2 * DTYPE_B

# ⭐ §4.1 那张「按大小排一遍」的表 —— 由常量生成，不手填。
#   ⛔ 这一节原来是张空支票：正文写着「这个顺序本身就是这一节的全部内容」，
#      然后**一张表一张图都没有**；而 4.2 第一句就是「正是照着这个顺序来的」。
#      四位评审各自撞到它。
N_PARAM = 671e9               # V3 总参数（激活参数是 37B，但显存按总量算）
# ⛔ 正文原来一律写「三千亿个参数」——&#160;源文件 29 处、渲染后 45 处，
#   而 V3 是 6,710 亿（激活 37B），**哪个口径都对不上**（2026-09-19 审计查出）。
#   它还坐在页面大标题和 §1 的标题里。⭐ 这一讲自己的招牌就是
#   「不标场景的数字没有意义」，所以不能拿一个约数当标题用。
#   现在由 N_PARAM 驱动，换模型就自动跟着走。
_NPARAM_CN = format(round(N_PARAM / 1e8), ",") + " 亿"
# ⭐ 笨办法要算多少年 ——&#160;原来是手算完手填「两万年」，跟「所有数由脚本算」
#   这条规矩不一致（2026-09-20 第 3 轮开讲时发现：讲的时候我当场又算了一遍）。
#   一次前向按 1 秒；一年 3.156e7 秒（365.25 天）。
_SEC_PER_YEAR  = 3.156e7
_NAIVE_YEARS   = N_PARAM / _SEC_PER_YEAR
_NAIVE_YEARS_CN = "两万" if 15000 < _NAIVE_YEARS < 25000 else "%.0f" % _NAIVE_YEARS
assert 21000 < _NAIVE_YEARS < 21500, "笨办法年数变了：%.0f" % _NAIVE_YEARS

# ══ 3.3b 的「两个旋钮」—— 这一格全部的论点就是一句「互为倒数」 ═══════
# ⛔ 数字虽然是编的（示意用），但**它们之间的关系是承重的**，所以照样钉住：
#    「该拧的圈数之比」必须正好是「梯度之比」的倒数 —— 这一条一旦不成立，
#    「SGD 正好拧反了」这个结论当场垮掉，而正文照样会把它印出来。
# ⭐ 这是 §5.4 那次的教训：唯一一个手打的数（7.1）就是唯一一个错的数。
_KNOB_ERR      = 1000           # 当前误差
_KNOB_A        = 100            # 甲的梯度：拧一格，误差变这么多（灵）
_KNOB_B        = 1              # 乙的梯度（钝）
_KNOB_TURNS_A  = _KNOB_ERR // _KNOB_A     # 甲要拧几格才消得掉
_KNOB_TURNS_B  = _KNOB_ERR // _KNOB_B
_KNOB_RATIO    = _KNOB_A // _KNOB_B       # SGD 给的步长之比
assert _KNOB_A * _KNOB_TURNS_A == _KNOB_ERR and _KNOB_B * _KNOB_TURNS_B == _KNOB_ERR, \
    "两个旋钮的圈数必须正好消掉误差，否则例子本身就是错的"
assert _KNOB_A / _KNOB_B == _KNOB_TURNS_B / _KNOB_TURNS_A, (
    "⛔ 「该拧的圈数」必须正好是「梯度」之比的倒数 —— 这是 3.3b 的全部论点。"
    "现在是 %s:%s vs %s:%s" % (_KNOB_A, _KNOB_B, _KNOB_TURNS_B, _KNOB_TURNS_A))
assert _KNOB_RATIO * _KNOB_B == _KNOB_A, "__KNOB_RATIO__ 必须真的是甲乙梯度之比"
assert _NPARAM_CN == "6,710 亿", _NPARAM_CN
TIB = 1024 ** 4
# 每参数的字节数 —— 拆法与 §3.1 一致（bf16 权重 2、bf16 梯度 2、
# fp32 主权重 4 ＋ 一阶矩 4 ＋ 二阶矩 4 ＝ 12）
LEDGER = [
    ("优化器状态", 12, "fp32 主权重 4 ＋ 一阶矩 <i>m</i> 4 ＋ 二阶矩 <i>v</i> 4",
     "只在<b>更新那一瞬间</b>用一次"),
    ("权重",        2, "bf16 那一份，前向反向都拿它算", "每一层都要读"),
    ("梯度",        2, "bf16，跟权重同形", "反向写、更新后就能扔"),
]
_LED_B = sum(r[1] for r in LEDGER)
_pct = lambda v: ("%.1f" % v).rstrip("0").rstrip(".")   # 12.5 要保留，75.0 要收掉
_rows = "".join(
    '<tr><td><b>%s</b></td><td class="num">%d B</td>'
    '<td class="num"><b>%.2f TiB</b></td><td class="num">%s%%</td>'
    '<td>%s</td><td><em>%s</em></td></tr>'
    % (nm, b, N_PARAM * b / TIB, _pct(100.0 * b / _LED_B), how, when)
    for nm, b, how, when in LEDGER)
_TBL_LEDGER = (
    '<table class="tbl"><thead><tr>'
    '<th>这一项</th><th class="num">每参数</th><th class="num">671B 上</th>'
    '<th class="num">占常驻</th><th>它是什么</th><th>什么时候用得上</th>'
    '</tr></thead><tbody>%s'
    '<tr class="sum"><td><b>常驻小计</b></td><td class="num"><b>%d B</b></td>'
    '<td class="num"><b>%.2f TiB</b></td><td class="num">100%%</td>'
    '<td colspan="2"><em>⭐ 跟 batch、跟序列长度<b>都无关</b> ——&nbsp;'
    '只要模型定了，这个数就定了。</em></td></tr>'
    '<tr><td><b>中间激活</b></td><td class="num">——</td>'
    '<td class="num"><b>看 batch</b></td><td class="num">——</td>'
    '<td>反向要用的那一堆中间结果（<a href="#s1-6">1.6</a>）</td>'
    '<td><em>⛔ 唯一一个<b>你自己能调</b>的 ——&nbsp;'
    '也是唯一一个能反超上面三项的</em></td></tr>'
    '</tbody></table>'
    % (_rows, _LED_B, N_PARAM * _LED_B / TIB))

_html = head + HERO + BODY + FOOT
_html = _html.replace("__TBL_PER_BYTE__", _TBL)
_SUBS = {}          # ⭐ 记下每一次替换，供 place_figs 之后补跑一遍
for _ph, _val in (("__ATT_PB_BASE__", "%.2f" % (_att_base[2] * GIB_F)),
                  ("__ATT_PB_LONG__", "%.2f" % (_att_long[2] * GIB_F)),
                  ("__ATT_VS_W__",    "%.0f%%" % (100 * _ATT_VS_WIDEST)),
                  ("__TIMES_LONG__",  "%.0f" % _TIMES_LONG),
                  ("__CHEAP_GIB__",   "%.2f GiB" % _CHEAP_GIB),
                  ("__CHEAP_TF__",    "%.2f TFLOP" % _CHEAP_TF),
                  ("__STEP_TF__",     "%.1f TFLOP" % _STEP_TF),
                  ("__SEL_PCT__",     "%.1f%%" % _SEL_PCT),
                  ("__SEL_SAVE__",    "%.0f%%" % _SEL_SAVE),
                  ("__EDGE__",        "%.1f" % _EDGE),
                  ("__W_BF16__",      format(_W_BF16_B / 2 ** 30, ",.0f")),
                  ("__ACT_XOVER__",   "%.0f" % _ACT_XOVER),
                  ("__WIDEST__",      format(W_WIDEST_V3, ",")),
                  ("__CROSS__",       format(int(round(_CROSS)), ",")),
                  ("__CROSS_K__",     "%.0fK" % (_CROSS / 1024)),
                  ("__NROWS__",       str(_NROWS)),
                  ("__WIDEST_PB__",   "%.2f" % _WIDEST_PB),
                  ("__RANK_BASE__",   str(_RANK_BASE)),
                  ("__RANK_LONG__",   str(_RANK_LONG)),
                  ("__KNOB_ERR__",     format(_KNOB_ERR, ",")),
                  ("__KNOB_A__",       str(_KNOB_A)),
                  ("__KNOB_B__",       str(_KNOB_B)),
                  ("__KNOB_TURNS_A__", format(_KNOB_TURNS_A, ",")),
                  ("__KNOB_TURNS_B__", format(_KNOB_TURNS_B, ",")),
                  ("__KNOB_RATIO__",   format(_KNOB_RATIO, ",")),
                  # ⛔ 2026-09-22：这四个 128K 的数原来是**手打在正文里**的
                  #   （71 GiB / 4.15 TiB / 177.89 GiB / 56 条）。这一轮改口径时
                  #   它们一个都没跟着动 —— ⭐ 判据还是那条：**算得出来的数
                  #   不许在正文里躺着**。现在它们跟 4K 那套同源。
                  ("__ACT_LAYER_L__", _sz(_LAYER_B * S_RATIO)),
                  ("__ACT_TOTAL_L__", _sz(_TOTAL_B * S_RATIO)),
                  ("__PEAK_L__",      _sz(_PEAK_B * S_RATIO)),
                  ("__WS_SEQ_L__",    "%.0f" % (RESIDENT_B / (_PEAK_B * S_RATIO))),
                  ("__NPARAM_CN__",   _NPARAM_CN),
                  ("__NAIVE_YEARS__", format(int(round(_NAIVE_YEARS)), ",")),
                  ("__NAIVE_YEARS_CN__", _NAIVE_YEARS_CN),
                  ("__MOE_O_PCT__",   _MOE_O_PCT),
                  ("__MOE_S_PCT__",   _MOE_S_PCT),
                  ("__MOE_ALL_PCT__", _MOE_ALL_PCT),
                  ("__ATT_PCT__",     _ATT_PCT)):
    assert _ph in _html, "正文里没有 %s" % _ph
    _html = _html.replace(_ph, _val)
    _SUBS[_ph] = _val
_html = _html.replace("__TBL_LEDGER__", _TBL_LEDGER)
_html = _html.replace("__TBL_SCALE__", _TBL_SCALE)
_html = _html.replace("__LOGITS__", _sz(_LOGITS_B))
for _ph, _val in (("__R_SMALL__", "%.0f" % _R_SMALL), ("__R_V3__", "%.1f" % _R_V3),
                  ("__X_SMALL__", "%.1f" % _x_small),
                  ("__R_SMALL_E__", "%.0f" % _R_SMALL_E),
                  ("__X_SMALL_E__", "%.1f" % _x_small_e)):
    assert _ph in _html, "正文里没有 %s" % _ph
    _html = _html.replace(_ph, _val)
    _SUBS[_ph] = _val
for _ph, _val in (("__PEAK__",        _sz(_PEAK_B)),
                  ("__CKPT__",        _sz(_CKPT_B)),
                  ("__INFLIGHT__",    _sz(_INFLIGHT_B)),
                  ("__RECOMP_X__",    "%.1f" % _RECOMP_X),
                  ("__UNDER__",       "%.0f%%" % (100 * (1 - _CKPT_B / _PEAK_B))),
                  ("__WS_SEQ_OLD__",  "%.0f" % (RESIDENT_B / _CKPT_B)),
                  ("__WS_SEQ__",      "%.0f" % _WS_SEQ),
                  ("__WS_TOK__",      "%.0f 万" % (_WS_TOK / 1e4))):
    assert _ph in _html, "正文里没有 %s" % _ph
    _html = _html.replace(_ph, _val)
    _SUBS[_ph] = _val
_html = _html.replace("__TBL_ACT_MLA__",
                      _act_tbl(_MLA_ROWS, S_BASE, "宽度", "小计"))
_html = _html.replace("__TBL_ACT_MOE__",
                      _act_tbl(_MOE_ROWS, S_BASE, "份数 × 宽度", "小计"))
for _ph, _val in (
        # ⛔ 2026-09-22：原来是 2 × 64512（派发 ＋ 专家输出），而派发那一份作废了。
        ("__ACT_NINE__",   _sz(64512 * DTYPE_B * S_BASE)),   # 只剩「专家输出 9 份」
        ("__ACT_LAYER__",  _sz(_LAYER_B)),
        ("__ACT_DENSE__",  _sz(_DENSE_B)),
        ("__ACT_TOTAL__",  _sz(_TOTAL_B)),
        ("__ATTN_SCORE__", _sz(_ATTN_SCORE_B))):
    assert _ph in _html, "正文里没有 %s" % _ph
    _html = _html.replace(_ph, _val)
    _SUBS[_ph] = _val

assert abs(_CROSS - 13107) < 1, "交叉点变了：%.0f" % _CROSS
# ⛔ 这两条原来钉的是 5,734（分母用了 d_model）。钉住一个错的值，assert 反而变成了保险箱 ——
#    所以现在改成钉「交点 ＝ 最宽线性层 ÷ 1.25」这条**关系**，外加宽度本身跟 §1.7 的表对账。
assert abs(_CROSS * 1.25 - W_WIDEST_V3) < 1e-6, "交点和最宽线性层脱钩了"
assert "5,734" not in _html.replace("早先写的是 <b>5,734</b>", "").replace(
    "交点报 5,734", ""), "正文里还留着旧交点 5,734"
# ⛔ 128K 锚点。⚠️ 省显存那个数 T09 从 53.50 变成 55.69 ——&#160;**这是修正不是漂移**：
#   旧表漏了 MLA 的两个 norm 输出和 Q 降维那份 layernorm 输出（都是 pb≈2 的白捡项）。
#   ⭐ 算力代价 48.95 TFLOP **一点没变**，因为补上的几行每字节代价几乎为零。
# ⛔⛔ 2026-09-19 再修一次：55.69 → 53.94。少掉的 1.75 GiB 就是「MLA 后的残差流」那一份 ——
#   它原来跟三个 RMSNorm 输出捆在一起按逐元素计价（白捡），实际重算它要跑 o_proj（输入宽 16,384），
#   比值 17.59 远在切线之外，所以它不该进「收下」那一批。算力代价 48.95 依旧没变（同样因为
#   它旧价几乎为零）。⭐ 这两次都是**修正**：省显存那一栏两次都在动，算力那一栏两次都没动。
# ⛔⛔ 2026-09-22 第三次动这一栏：53.94 → 38.19。少掉的 15.75 GiB 就是
#   「派发九份」那一项 —— 它原来按逐元素（白捡）计价，所以整份都在「收下」那一批里。
#   ⭐ 算力代价 48.95 **第三次一点没变**（它的每字节代价本来就≈0）。
#   这一栏三次修正全在省显存那一侧、算力那一侧一次没动 —— 这本身就是个自洽性信号。
assert abs(_CHEAP_GIB * S_RATIO - 38.19) < 0.05 and abs(_CHEAP_TF * S_RATIO - 48.95) < 0.1, \
    "「比值小于 3 全收下」对不上 128K 锚点：%.2f / %.2f" % (_CHEAP_GIB * S_RATIO, _CHEAP_TF * S_RATIO)
# ⛔ 2026-09-22：77.8% → 71.2%。派发那一份（占池子一大块、且几乎白捡）没了，
#   剩下的池子里「便宜项」的占比自然降下来。⭐ 论点（选择性一招吃掉七成多）不变。
assert abs(_SEL_SAVE - 71.2) < 0.1, "选择性换掉池子的比例变了：%.1f%%" % _SEL_SAVE

# ⭐ §4.1 那张表跟散在正文里的那几个数必须对得上。
#   ⛔ 它们分处两节、相隔三千行 —— 正是「改了一处忘了另一处」的经典产地，
#      而这一讲自己已经因为讲义没跟着改而被评审抓到过一次。
assert _LED_B == 16, "每参数字节数不是 16 了：%d —— §3.1 的拆法改了？" % _LED_B
for _n, _v, _want in (("优化器状态", 12, 7.32), ("权重", 2, 1.22),
                      ("常驻小计", _LED_B, 9.76)):
    _tib = N_PARAM * _v / TIB
    assert abs(_tib - _want) < 0.005, \
        "§4.1 的表算出 %s ＝ %.3f TiB，可正文里写的是 %.2f" % (_n, _tib, _want)
assert "权重 1.22 ＋ 梯度 1.22 ＋ 优化器状态 <b>7.32</b>" in _html, \
    "§5.1 那句拆分被改过了 —— §4.1 的表要跟着核一遍"

# ⛔ 标签配对：全课落点那个 <h3> 的开标签曾经整个丢了，只剩 </h3>。
#   后果不是「样式不对」——是**全讲的落点渲染成裸正文、不进目录、锚点不存在**，
#   而页面照样构建通过、照样上线。四位评审各自看见它，我自己读了几十遍没看见。
#   ⭐ 判据：**会静默上线的错，必须让它在构建时炸。**
for _tag in ("h2", "h3", "section", "div"):
    _o = len(re.findall(r"<%s[ >]" % _tag, _html))
    _c = _html.count("</%s>" % _tag)
    assert _o == _c, (
        "<%s> 开 %d 个、闭 %d 个 —— 差 %d。"
        "少一个开标签的话，那一段会当成正文渲染，构建不会报错，但目录里它不存在。"
        % (_tag, _o, _c, _c - _o))

for ph, (what, figs, asks) in PLAN.items():
    assert ph in _html, "正文里没有 %s —— 章写完了要连这一行一起删" % ph
    _html = _html.replace(ph, todo(what, figs, asks))

# ⭐ 这一份是**要投屏讲的**，所以装折叠开关，默认只剩图。
_html = P.place_figs(_html, FIGS)

# ⛔⛔ place_figs 在上面那几轮替换**之后**才把图注注入，所以图注里的占位符
#   一轮都没被替换到 ——&#160;它们原样漏进了成品。
#   ⭐ 而原来的断言只查「替换前在不在」（`assert _ph in _html`），
#     **不查「替换后还剩没剩」** ——&#160;于是 __NPARAM_CN__ 在线上漏了半天没人发现。
#   （2026-09-20 第 3 轮开讲时撞到：图注里写「代价差 __NAIVE_YEARS_CN__年」。）
#   判据：**替换类操作要同时有前置断言和后置断言。** 只查前置，
#   等于只保证「我动手了」，不保证「动干净了」。
for _ph, _val in _SUBS.items():
    _html = _html.replace(_ph, _val)
_leak = sorted(set(re.findall(r"__[A-Z][A-Z_0-9]*__", _html)))
assert not _leak, "占位符没落地，漏进成品：%s" % "、".join(_leak)
_html = P.add_figonly_toggle(_html)
# ⛔⛔ 2026-09-20：T12 换主线时改了 SECTIONS 的标题，**却没改正文里的 <h2>** ——
#   而吸顶目录是从 <h2> 长出来的，于是目录上挂了一整套旧标题，一挂就是八轮。
#   ⭐ 判据：**同一个东西有两份写法时，必须断言它们一致** ——&#160;
#     「改一处忘另一处」不会报错，它只是静默地展示旧的那份。
_h2 = dict(re.findall(r'<section id="(s[^"]+)"><div class="wrap"><div class="stn">'
                      r'<span class="badge">[^<]*</span><h2>(.*?)</h2>', _html, re.S))
for _sid, _num, _title in SECTIONS:
    _strip = lambda t: re.sub(r"<[^>]+>", "", t).replace("&nbsp;", " ").strip()
    # ⭐ SECTIONS 里的标题还带着占位符（它在替换发生前就被 TOC 用掉了），
    #   所以比较前要对它做同一次替换 ——&#160;否则这条断言会把「已正确替换」误报成不一致。
    _want_raw = _title.replace("__NPARAM_CN__", _NPARAM_CN)
    _got, _want = _strip(_h2.get(_sid, "")), _strip(_want_raw)
    assert _got == _want, \
        "SECTIONS 跟正文 <h2> 对不上：%s\n  SECTIONS：%s\n  正文：%s" % (_sid, _want, _got)
print("   ✅ SECTIONS 与正文 %d 个 <h2> 逐字一致" % len(SECTIONS))

P.finish(_html, OUT, SECTIONS, "topic-04.html")

# ⛔ 站内锚点必须落地 —— **查的是写出去的那份成品**，不是中间变量。
#   小节 id 是 P.finish() 生成 tocbar 时才补上的，在它之前查会全军覆没。
#   ⭐ 这一条防的是：交叉引用指向一个**真实存在但内容不相干**的小节
#      （「6.4 那个清单」实际在 3.7、「1.2 那三条边界」实际在 1.7）。
#      死链会被发现，跳错不会 —— 所以它比死链更该由机器盯。
_final = io.open(OUT, encoding="utf-8").read()   # OUT 已是完整文件路径
_ids = set(re.findall(r'\bid="([^"]+)"', _final))
_bad = sorted({h for h in re.findall(r'href="#([^"]+)"', _final)
               if h and not h.startswith("!") and h not in _ids})
# ⭐⭐ 上面那段注释说这条断言「防的是跳错」——&#160;可它只查了 id 在不在，
#    跳错一个字都拦不住（2026-09-19 红队查出六处：五处「3.3」实际在 3.3b，
#    一处「2.6」实际在 2.5）。现在把那句话真的实现出来：
#    **凡是链接文字本身就是节号的，它必须落在同号的那一节上。**
_CN = dict(zip("零一二三四五六七八九", range(10)))
_titles = dict(re.findall(r'\bid="(s[^"]+)"[^>]*>(.{0,18})', _final))
_mis = []
for _href, _txt in re.findall(r'href="#(s[^"]+)"[^>]*>(.*?)</a>', _final, re.S):
    _t = re.sub(r"<[^>]+>", "", _txt).strip()
    if not re.fullmatch(r"\d+(?:\.\d+[a-z]?)?", _t):
        continue                                  # 「上面那张图」这类文字链不查
    _m = re.fullmatch(r"s(\d+)-(\d+[a-z]?)", _href)
    if _m:                                        # 指向小节 → 号必须一模一样
        if "%s.%s" % _m.groups() != _t:
            _mis.append("%s → #%s（同粒度但跳到了别的小节）" % (_t, _href))
    elif re.fullmatch(r"s[零一二三四五六七八九]", _href):
        if _CN[_href[1]] != int(_t.split(".")[0]):   # 指向整章 → 至少章号要对
            _mis.append("%s → #%s（连章都不对）" % (_t, _href))
assert not _mis, "节号链接跳错：\n  " + "\n  ".join(sorted(set(_mis)))

# ⭐ 列表条数 lint 已上移到 topic03_page.lint_list_counts（finish 里调）——
#   同一个毛病别的专题一样会犯，判据放在共用框架里才拦得住。

# ⛔⛔⛔ 2026-09-20 第 20 轮。这一轮的错（判据③ 漏了前提）在**三个文件**里各有一份，
#   而这已经是本批第四次栽在「同一个事实有 N 个落点就有 N 个版本」上了：
#   图 vs 文（第 16 轮）、节标题 vs 时间表（第 18 轮）、手打数 vs 算出来的数（第 19 轮）。
#   ⭐ 判据：**副本不消灭，就得上锁。** 下面几句是四条判据里承重的原话，
#     总纲 index.html 里有副本 ——&#160;改一处不改另一处，build 当场失败。
_MIRROR = ["每省一字节要付多少 FLOPs", "长得快的那个起点更低",
           "稳没稳", "质量掉没掉"]
_idx = os.path.join(WEB, "index.html")
if os.path.exists(_idx):
    _idx_html = io.open(_idx, encoding="utf-8").read()
    _lost = [_p for _p in _MIRROR if _p in _final and _p not in _idx_html]
    assert not _lost, ("四条判据改了，总纲 index.html 没跟着改：%s\n"
                       "   ⭐ 两处都要改 ——&#160;读者常常只看总纲那一份。"
                       % "、".join(_lost))
    print("   ✅ 四条判据与总纲 index.html 逐句对上（%d 句）" % len(_MIRROR))

assert not _bad, (
    "这些站内锚点指向不存在的 id：%s\n"
    "⭐ 小节 id 形如 s3-7 / s6-6，节级形如 s六。" % "、".join(_bad))
print("   ✅ 站内锚点 %d 个全部落地" % len(re.findall(r'href="#', _final)))
